#include <bits/stdc++.h>
using namespace std;

const int oo = 1000000000;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    if (n > m) {
        swap(n, m);
    }

    int size = 1 << n;
    vector<vector<int>> curr(size, vector<int>(size, oo));
    for (int i = 0; i < size; i++) {
        curr[0][i] = 0;
    }

    for (int j = 0; j < m; j++) {
        vector<vector<int>> next(size, vector<int>(size, oo));
        for (int c0 = 0; c0 < size; c0++) {
            for (int c1 = 0; c1 < size; c1++) {
                if (curr[c0][c1] != oo) {
                    int limit = (j == m - 1) ? 1 : size;
                    for (int c2 = 0; c2 < limit; c2++) {
                        int done = 0;
                        for (int i = 0; i < n; i++) {
                            if (((1 << i) & c1) == 0) {
                                int up = i - 1;
                                int down = i + 1;
                                if (up >= 0 && ((1 << up) & c1) != 0)
                                    done |= 1 << i;
                                if (down < n && ((1 << down) & c1) != 0)
                                    done |= 1 << i;
                                if (((1 << i) & c0) != 0)
                                    done |= 1 << i;
                                if (((1 << i) & c2) != 0)
                                    done |= 1 << i;
                            }
                        }
                        next[c1][c2] = std::min(next[c1][c2], curr[c0][c1] + n - __builtin_popcount(done));
                    }
                }
            }
        }
        curr = move(next);
    }

    int res = oo;
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            res = min(res, curr[i][j]);
        }
    }

    cout << n * m - res << "\n";

    return 0;
}
